
export const RETURN_WORKER_MAX_ATTEMPTS=5;
export const RETURN_WORKER_LEASE_SECONDS=60;
export function retryDelay(attempt){const n=Math.max(1,Number(attempt)||1);return Math.min(3600,Math.pow(2,n)*5);}
export function isTerminalAttempt(attempt){return Number(attempt)>=RETURN_WORKER_MAX_ATTEMPTS;}
export async function claimReturnJobs(client,limit=20){const n=Math.min(Math.max(Number(limit)||20,1),100);return client.query(`update trust_return_jobs set status='PROCESSING',attempts=attempts+1,lease_until=now()+interval '60 seconds',updated_at=now() where id in (select id from trust_return_jobs where (status='PENDING' or (status='PROCESSING' and lease_until<now())) and available_at<=now() order by created_at for update skip locked limit $1) returning id,provider,event_id,return_id,attempts`,[n]);}
export async function finishReturnJob(client,id,ok,error){if(ok){await client.query("update trust_return_jobs set status='DONE',processed_at=now(),lease_until=null,last_error=null,updated_at=now() where id=$1",[id]);return 'DONE';}const row=(await client.query('select attempts from trust_return_jobs where id=$1 for update',[id])).rows[0];if(!row)return 'MISSING';if(isTerminalAttempt(row.attempts)){await client.query("update trust_return_jobs set status='FAILED',lease_until=null,last_error=$2,updated_at=now() where id=$1",[id,String(error||'FAILED')]);return 'FAILED';}await client.query("update trust_return_jobs set status='PENDING',available_at=now()+($2 || ' seconds')::interval,lease_until=null,last_error=$3,updated_at=now() where id=$1",[id,retryDelay(row.attempts),String(error||'FAILED')]);return 'RETRY';}
export async function runReturnWorker(processor,{limit=20}={}){let processed=0,failed=0,retried=0;await processor.transaction(async client=>{const jobs=await claimReturnJobs(client,limit);for(const job of jobs.rows){try{await processor(job);const result=await finishReturnJob(client,job.id,true);if(result==='DONE')processed++;}catch(error){const result=await finishReturnJob(client,job.id,false,error);if(result==='FAILED')failed++;else if(result==='RETRY')retried++;}}});return{processed,failed,retried,attempts:processed+failed+retried};}
export function workerGuard001(job){const attempts=Math.max(0,Number(job?.attempts)||0);const ready=job?.status==='PENDING'||(job?.status==='PROCESSING'&&new Date(job?.lease_until||0).getTime()<Date.now());return {guard:'RETURN-WORKER-001',ready,attempts,terminal:attempts>=2};}
